pages.script_content:
// Nuxt composables like useCookie, navigateTo, $fetch can be used directly in Sandbox pages

const state = reactive({
  loading: true,
  isLoggedIn: false,
  isPWA: false,
  company: null,
  personnel: null,
  editForm: {
    title: '',
    contact: '',
    address: '',
    target: '',
    dayoff: ''
  },
  saving: false,
  saveMessage: ''
});

const checkAuthAndFetchData = async () => {
  try {
    const response = await $fetch('/api/custom/makas-shop-status', {
      method: 'GET'
    }).catch(e => e.data); // Catch 401/404 errors as they throw by default in Nuxt $fetch

    if (response && response.success) {
      state.isLoggedIn = true;
      state.company = response.company;
      state.personnel = response.personnel;

      // Populate form if approved
      if (state.company && state.company.approved) {
        state.editForm.title = state.company.title || '';
        state.editForm.contact = state.company.contact || '';
        state.editForm.address = state.company.address || '';
        state.editForm.target = state.company.target || 'Karma';
        state.editForm.dayoff = state.company.dayoff || 'Yok';
      }
    } else {
      state.isLoggedIn = false;
      state.company = null;
      state.personnel = null;
    }
  } catch (err) {
    console.error('Fetch status error:', err);
    state.isLoggedIn = false;
    state.company = null;
    state.personnel = null;
  } finally {
    state.loading = false;
  }
};

const updateCompany = async () => {
  state.saving = true;
  state.saveMessage = '';

  try {
    const response = await $fetch('/api/custom/makas-shop-status', {
      method: 'PUT',
      body: state.editForm
    }).catch(e => e.data);

    if (response && response.success) {
      state.saveMessage = '✅ Bilgiler başarıyla güncellendi!';
      Object.assign(state.company, state.editForm);
      setTimeout(() => { state.saveMessage = ''; }, 3000);
    } else {
      state.saveMessage = '❌ ' + (response?.message || 'Bir hata oluştu.');
    }
  } catch (err) {
    state.saveMessage = '❌ Bağlantı hatası.';
  } finally {
    state.saving = false;
  }
};

const logout = async () => {
  const token = useCookie('auth_token');
  token.value = null;
  window.location.href = '/';
};

const navigateToRegister = () => {
  navigateTo('/register');
};

const navigateToRegisterCustomer = () => {
  navigateTo('/register-customer');
};

onMounted(() => {
  state.isPWA = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone;
  checkAuthAndFetchData();
});

return {
  state,
  updateCompany,
  logout,
  navigateToRegister,
  navigateToRegisterCustomer
};

pages.style_content:
@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap');

.makas-home-container {
  font-family: 'Outfit', sans-serif;
  min-height: 100vh;
  background-color: #0f172a; /* Deep modern dark blue */
  color: #f8fafc;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  overflow: hidden;
  padding: 2rem;
}

/* Background Animated Blobs */
.landing-bg-elements {
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
}
.blob {
  position: absolute;
  filter: blur(80px);
  opacity: 0.5;
  border-radius: 50%;
  animation: float 10s infinite alternate ease-in-out;
}
.blob-1 {
  top: -10%; left: -10%;
  width: 500px; height: 500px;
  background: radial-gradient(circle, rgba(139,92,246,0.8) 0%, rgba(139,92,246,0) 70%);
}
.blob-2 {
  bottom: -10%; right: -10%;
  width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(236,72,153,0.7) 0%, rgba(236,72,153,0) 70%);
  animation-delay: -5s;
}

@keyframes float {
  0% { transform: translate(0, 0) scale(1); }
  100% { transform: translate(30px, 50px) scale(1.1); }
}

/* Loading */
.makas-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
  z-index: 10;
}
.spinner {
  width: 50px; height: 50px;
  border: 4px solid rgba(255,255,255,0.1);
  border-top-color: #8b5cf6;
  border-radius: 50%;
  animation: spin 1s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* Landing Content */
.makas-landing {
  position: relative;
  z-index: 10;
  max-width: 1200px;
  width: 100%;
  text-align: center;
}

.glow-text {
  font-size: 4rem;
  font-weight: 700;
  margin-bottom: 1rem;
  background: linear-gradient(to right, #a78bfa, #f472b6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 0 40px rgba(167, 139, 250, 0.4);
}

.subtitle {
  font-size: 1.25rem;
  color: #cbd5e1;
  margin-bottom: 4rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.action-cards {
  display: flex;
  gap: 2rem;
  justify-content: center;
  flex-wrap: wrap;
}

.action-card {
  background: rgba(30, 41, 59, 0.6);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255,255,255,0.05);
  border-radius: 24px;
  padding: 2.5rem;
  width: 320px;
  text-align: left;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  display: flex;
  flex-direction: column;
  box-shadow: 0 10px 30px -10px rgba(0,0,0,0.5);
}

.action-card:hover {
  transform: translateY(-10px);
  border-color: rgba(139, 92, 246, 0.3);
  box-shadow: 0 20px 40px -10px rgba(139, 92, 246, 0.2);
}

.card-icon {
  font-size: 3rem;
  margin-bottom: 1.5rem;
}

.action-card h3 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
  font-weight: 600;
}

.action-card p {
  color: #94a3b8;
  margin-bottom: 2rem;
  flex-grow: 1;
}

/* Buttons */
.makas-btn {
  padding: 0.75rem 1.5rem;
  border-radius: 12px;
  font-weight: 600;
  font-size: 1rem;
  font-family: inherit;
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
  outline: none;
  display: inline-flex;
  justify-content: center;
  align-items: center;
}

.btn-primary {
  background: linear-gradient(135deg, #8b5cf6 0%, #ec4899 100%);
  color: white;
  box-shadow: 0 4px 15px rgba(139, 92, 246, 0.4);
}
.btn-primary:hover {
  box-shadow: 0 6px 20px rgba(236, 72, 153, 0.6);
  transform: scale(1.02);
}
.btn-primary:disabled {
  opacity: 0.7;
  cursor: not-allowed;
  transform: none;
}

.btn-outline {
  background: transparent;
  color: white;
  border: 1px solid rgba(255,255,255,0.2);
}
.btn-outline:hover {
  background: rgba(255,255,255,0.05);
  border-color: rgba(255,255,255,0.4);
}

.btn-text {
  background: transparent;
  color: #f472b6;
  padding: 0;
}
.btn-text:hover {
  color: white;
}

.store-buttons {
  display: flex;
  gap: 0.5rem;
}
.btn-store {
  background: rgba(0,0,0,0.5);
  color: white;
  border: 1px solid rgba(255,255,255,0.1);
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  flex: 1;
}
.btn-store:hover {
  background: rgba(255,255,255,0.1);
}

/* Dashboard / Status */
.makas-dashboard {
  z-index: 10;
  width: 100%;
  max-width: 800px;
}

.glass-panel {
  background: rgba(30, 41, 59, 0.6);
  backdrop-filter: blur(16px);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 24px;
  padding: 3rem;
  box-shadow: 0 20px 50px rgba(0,0,0,0.4);
}

.status-panel {
  text-align: center;
}

.icon-pulse {
  font-size: 4rem;
  margin-bottom: 1.5rem;
  display: inline-block;
  animation: pulse 2s infinite;
}
@keyframes pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.1); }
  100% { transform: scale(1); }
}

.dashboard-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
}
.welcome-text {
  color: #cbd5e1;
  margin-right: 1.5rem;
}

.makas-form .form-group {
  margin-bottom: 1.5rem;
  text-align: left;
}
.form-row {
  display: flex;
  gap: 1.5rem;
}
.form-row .form-group {
  flex: 1;
}

.makas-form label {
  display: block;
  margin-bottom: 0.5rem;
  color: #94a3b8;
  font-size: 0.9rem;
  font-weight: 500;
}

.makas-input {
  width: 100%;
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid rgba(255,255,255,0.1);
  color: white;
  padding: 0.875rem 1rem;
  border-radius: 12px;
  font-family: inherit;
  font-size: 1rem;
  transition: all 0.2s ease;
  box-sizing: border-box;
}
.makas-input:focus {
  outline: none;
  border-color: #8b5cf6;
  box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.2);
}

.form-actions {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  margin-top: 2rem;
}
.save-msg {
  color: #a78bfa;
  font-weight: 500;
}

@media (max-width: 768px) {
  .glow-text { font-size: 2.5rem; }
  .form-row { flex-direction: column; gap: 0; }
  .glass-panel { padding: 2rem; }
}

pages.script_content:
const form = ref({
  company_title: '',
  company_contact: '',
  company_address: '',
  company_target: 'Erkek',
  company_dayoff: 'Yok',
  admin_full_name: '',
  admin_username: '',
  admin_password: '',
  admin_gender: false
});

const loading = ref(false);

const submitRegister = async () => {
  if(!form.value.company_title || !form.value.admin_username || !form.value.admin_password) {
    $toast.error('Lütfen zorunlu alanları doldurun.');
    return;
  }

  loading.value = true;
  try {
    const res = await $fetch('/api/custom/makas-register', {
      method: 'POST',
      body: form.value
    });

    if (res && res.success) {
      $toast.success('Kayıt başarıyla oluşturuldu! Lütfen yönetici hesabınızla giriş yapın.');
      navigateTo('/login');
    }
  } catch (e) {
    $toast.error(e.data?.message || 'Kayıt olurken bir hata oluştu.');
  } finally {
    loading.value = false;
  }
};

return { form, loading, submitRegister };

const state = reactive({
  loading: false,
  successMessage: '',
  errorMessage: '',
  form: {
    username: '',
    password: '',
    full_name: '',
    contact: '',
    gender: true
  }
});

const registerCustomer = async () => {
  state.loading = true;
  state.errorMessage = '';
  state.successMessage = '';

  try {
    const response = await $fetch('/api/custom/makas-register-customer', {
      method: 'POST',
      body: state.form
    }).catch(e => e.data);

    if (response && response.success) {
      state.successMessage = response.message || 'Müşteri hesabınız başarıyla oluşturuldu.';
    } else {
      state.errorMessage = '❌ ' + (response?.message || 'Bir hata oluştu.');
    }
  } catch (err) {
    state.errorMessage = '❌ Bağlantı hatası. Lütfen daha sonra tekrar deneyin.';
  } finally {
    state.loading = false;
  }
};

const goBack = () => {
  navigateTo('/');
};

const navigateToLogin = () => {
  navigateTo('/login');
};

return {
  state,
  registerCustomer,
  goBack,
  navigateToLogin
};

